FUNCTION_BLOCK FB_GlassFloat_LOR_AtmosphereCurtain
(*
========================================================================================================================
  PROJECT      : ULTRA-HIGH QUALITY FLOAT GLASS PRODUCTION LINE (950 METRIC TONS/DAY)
  SUBSYSTEM    : TIN BATH TO ANNEALING LEHR TRANSITION & DROSS BOX ATMOSPHERIC BARRIER
  EQUIPMENT    : MOTORIZED LIFT-OUT ROLLERS (LOR #1, #2, #3) & N2/H2 REDUCING ATMOSPHERE CURTAINS
  DESIGNATION  : SIL-3 / EN 61508 / NFPA 86 (CLASS C ATMOSPHERE) / IEC 61131-3 3RD EDITION COMPLIANT
  AUTHOR       : PRINCIPAL AUTOMATION FELLOW & CYBER-PHYSICAL SYSTEMS CHAIR (LUMINA SWARM)
------------------------------------------------------------------------------------------------------------------------
  CYBER-PHYSICAL SYSTEM & THEORETICAL FORMULATION:

  1. GLASS RIBBON VISCOELASTIC KINEMATICS AT BATH EXIT TRANSITION:
     As the continuous soda-lime-silica glass ribbon leaves the molten tin bath surface (~605 deg C) and transitions
     over the exit lip onto the lift-out rollers (LOR #1, LOR #2, LOR #3) into the annealing lehr inlet (~550 deg C),
     it passes through the critical viscoelastic transition regime.
     The temperature-dependent dynamic shear viscosity eta(T) follows the Vogel-Fulcher-Tammann (VFT) law:
         log10(eta(T)) = A_vft + (B_vft / (T - T0_vft))
     Between 605 deg C and 550 deg C, eta increases by approximately 1.5 orders of magnitude (10^7.2 to 10^8.7 dPa*s).
     Consequently, mechanical draw strain rate (epsilon_dot) and thermal shrinkage (d(epsilon_th)/dt) interact:
         sigma_tension(t) = E_eff(T) * epsilon_draw(t) + eta_eff(T) * (d(epsilon_draw)/dt)
     Longitudinal thermal contraction is governed by the linear thermal expansion coefficient alpha_th = 9.0e-6 K^-1:
         v_contraction_loss = alpha_th * (T_bath_exit - T_lehr_inlet) * v_line
     Any speed mismatch between the molten tin bath ribbon speed, LOR cascade speeds, and the lehr drive induces:
       a) Excessive tension (>1100 N): Causes ribbon necking, edge thinning, waviness, and catastrophic ribbon snap.
       b) Insufficient tension (<180 N): Causes ribbon sag into the dross box, scuffing against graphite bottom seals,
          buckling, and severe optical distortion (diopter wave defects).

  2. MULTI-AXIS LIFT-OUT ROLLER (LOR) ELECTRONIC LINE SHAFT (ELS) SYNCHRONIZATION:
     LOR #1, LOR #2, and LOR #3 are individually driven by vector-controlled servomotors via ceramic coupling shafts.
     To establish stable ribbon transition, a strictly positive draw taper profile is maintained:
         v_LOR1_ref = v_TinBath * (1.0 + delta_draw_1)
         v_LOR2_ref = v_LOR1    * (1.0 + delta_draw_2)
         v_LOR3_ref = v_LOR2    * (1.0 + delta_draw_3)
     where delta_draw_i is dynamically adapted via load-cell feedback and ribbon thickness tracking.
     Thermal expansion of roller diameters (fused silica / graphite sleeves) is compensated cyclically:
         D_roller_eff(T) = D_roller_nom * (1.0 + alpha_roller * (T_roller - 20.0))

  3. TIN BATH DROSS BOX N2/H2 PROTECTIVE ATMOSPHERE BARRIER:
     The molten tin bath relies on a reducing blanket gas (92-96% N2, 4-8% H2) to prevent tin oxidation:
         Sn(l) + 1/2 O2(g) <===> SnO(g)
         SnO(g) + 1/2 O2(g) <===> SnO2(s) (Surface Dross / Pinhead Defects)
         SnO(g) + H2(g) <===> Sn(l) + H2O(g) (Hydrogen Regeneration Reduction)
     At the lehr exit transition, the ribbon exits through a dross box equipped with graphite bottom blocks, top carbon
     curtains, and gas barrier knives. A positive differential pressure (Delta_P = P_bath - P_lehr >= +0.12 mbar)
     must be enforced continuously. If Delta_P drops below +0.03 mbar, atmospheric air ingresses, causing rapid oxygen
     spikes (>10 ppm), resulting in catastrophic tin dross deposits on the bottom surface of the glass ribbon.

  4. TRIPLE MODULAR REDUNDANCY (2oo3 TMR) DIFFERENTIAL PRESSURE SENSING:
     Three high-precision differential pressure transmitters monitor the bath-to-lehr barrier pressure.
     Cross-channel divergence checks identify drifting or blocked impulse lines, dynamically degrading from
     2oo3 to 2oo2, 1oo1, or failsafe purge boost.

  5. DISCRETE-TIME STATE-SPACE MODEL PREDICTIVE CONTROL (MPC):
     A multivariable linearized model represents the coupled mechanical and atmospheric dynamics:
         x(k+1) = A * x(k) + B * u(k) + E * d(k)
         y(k)   = C * x(k)
     State vector:
         x = [ delta_v_sync (m/min), delta_F_tension (N), delta_P_curtain (mbar), delta_C_O2 (ppm) ]^T
     Control inputs:
         u = [ delta_v_LOR_trim (m/min), delta_Q_N2_cmd (Nm3/h), delta_Q_H2_cmd (Nm3/h) ]^T
     Disturbances:
         d = [ delta_T_glass (deg C), delta_v_lehr_dist (m/min) ]^T
========================================================================================================================
*)

VAR_INPUT
    (* --- System Safety and Supervisory Permissives --- *)
    bMasterEnable                   : BOOL;     (* Master process enable permissive [TRUE=Run Permitted] *)
    bSafetyEStopOk                  : BOOL;     (* Hardwired SIL-3 emergency stop safety loop [TRUE=Healthy, FALSE=Tripped] *)
    bAutoModeSelect                 : BOOL;     (* Supervisory mode selector: TRUE = Closed-Loop MPC, FALSE = Coordinated Manual *)

    (* --- Mechanical Kinematic & Line Speed Inputs --- *)
    rLehrMasterSpeed_mpm            : REAL;     (* Annealing lehr virtual master line speed reference [m/min] (1.0 .. 30.0) *)
    rTinBathRibbonSpeed_mpm         : REAL;     (* Upstream tin bath optical laser Doppler ribbon speed [m/min] (1.0 .. 30.0) *)
    rLOR1_ActualSpeed_mpm           : REAL;     (* Lift-out roller 1 encoder actual feedback speed [m/min] (1.0 .. 32.0) *)
    rLOR2_ActualSpeed_mpm           : REAL;     (* Lift-out roller 2 encoder actual feedback speed [m/min] (1.0 .. 32.0) *)
    rLOR3_ActualSpeed_mpm           : REAL;     (* Lift-out roller 3 encoder actual feedback speed [m/min] (1.0 .. 32.0) *)
    rRibbonTensionFeedback_N        : REAL;     (* LOR entry pivoting load cell ribbon tension measurement [N] (0.0 .. 1500.0) *)

    (* --- Thermal Process Measurements --- *)
    rGlassRibbonTemp_DegC           : REAL;     (* Infrared optical pyrometer glass temperature at exit lip [deg C] (500.0 .. 700.0) *)
    rLOR_BottomRollTemp_DegC        : REAL;     (* Contact pyrometer temperature of LOR #1 carbon sleeve [deg C] (400.0 .. 650.0) *)
    rDrossBoxCavityTemp_DegC        : REAL;     (* Internal cavity thermocouple for dross box atmosphere [deg C] (300.0 .. 600.0) *)
    rGlassThickness_mm              : REAL;     (* Gamma/laser thickness gauge reading across ribbon centerline [mm] (1.5 .. 25.0) *)

    (* --- Atmospheric Differential Pressure & Chemical Instrumentation --- *)
    rBathExitDiffPress_Sens1_mbar   : REAL;     (* Redundant differential pressure sensor 1 (Bath to Lehr) [mbar] (0.00 .. 2.00) *)
    rBathExitDiffPress_Sens2_mbar   : REAL;     (* Redundant differential pressure sensor 2 (Bath to Lehr) [mbar] (0.00 .. 2.00) *)
    rBathExitDiffPress_Sens3_mbar   : REAL;     (* Redundant differential pressure sensor 3 (Bath to Lehr) [mbar] (0.00 .. 2.00) *)
    rNitrogenCurtainFlow_Nm3h       : REAL;     (* Total nitrogen curtain header flow meter [Nm3/h] (0.0 .. 500.0) *)
    rHydrogenCurtainFlow_Nm3h       : REAL;     (* Total hydrogen reducing trim flow meter [Nm3/h] (0.0 .. 60.0) *)
    rOxygenPpm_BathExit_ppm         : REAL;     (* Zirconia cell oxygen trace analyzer at dross box exit [ppm] (0.0 .. 100.0) *)
    bGraphiteSealWearAlarm          : BOOL;     (* Contact limit sensor indicating graphite bottom seal wear limit reached *)
END_VAR

VAR_OUTPUT
    (* --- Kinematic Actuation & Drive Reference Setpoints --- *)
    bSystemReady                    : BOOL;     (* System operational readiness indicator [TRUE=Ready/Active] *)
    bDegradedModeActive             : BOOL;     (* Degraded operational status active (TMR loss or encoder fallback) *)
    rLOR1_SpeedSetpoint_mpm         : REAL;     (* Lift-Out Roller 1 vector VFD synchronized speed reference [m/min] *)
    rLOR2_SpeedSetpoint_mpm         : REAL;     (* Lift-Out Roller 2 vector VFD synchronized speed reference [m/min] *)
    rLOR3_SpeedSetpoint_mpm         : REAL;     (* Lift-Out Roller 3 vector VFD synchronized speed reference [m/min] *)
    rCalculatedDraw_Pct             : REAL;     (* Total calculated glass draw elongation ratio across LOR table [%] *)

    (* --- Atmosphere Actuation Commands --- *)
    rN2CurtainValveCmd_Pct          : REAL;     (* Nitrogen atmosphere curtain flow control valve demand [%] (0.0 .. 100.0) *)
    rH2CurtainValveCmd_Pct          : REAL;     (* Hydrogen reducing trim flow control valve demand [%] (0.0 .. 100.0) *)
    bAtmosphereSealEstablished      : BOOL;     (* Certified positive reducing seal verified across lehr interface *)

    (* --- Diagnostics, Status Words, and Validated Telemetry --- *)
    rVotedExitPressure_mbar         : REAL;     (* 2oo3 TMR resolved validated differential pressure [mbar] *)
    wAlarmWord                      : WORD;     (* ISA-18.2 packed alarm word (Bit 0: EStop, Bit 1: PressLow, etc.) *)
    wSystemStatusWord               : WORD;     (* High-level controller internal state and diagnostic word *)
END_VAR

VAR
    (* --- State Machine Registers --- *)
    iState                          : INT := 0; (* Active operational state index *)
    iPreviousState                  : INT := 0; (* Historical state transition tracker *)

    (* --- Triple Modular Redundancy (2oo3) Validation Registers --- *)
    bSensor1_Valid                  : BOOL := TRUE;
    bSensor2_Valid                  : BOOL := TRUE;
    bSensor3_Valid                  : BOOL := TRUE;
    iHealthySensorCount             : INT  := 3;
    rDelta12                        : REAL := 0.0;
    rDelta23                        : REAL := 0.0;
    rDelta31                        : REAL := 0.0;
    rTmrToleranceLimit              : REAL := 0.050; (* Maximum permissible inter-channel divergence [mbar] *)

    (* --- Linearized Discrete-Time State-Space Model Matrices (dt = 0.5 s) --- *)
    (* State Vector:
         x[0] = delta_v_sync (Speed tracking error between LOR cascade and master [m/min])
         x[1] = delta_F_tension (Deviation from optimal ribbon tension setpoint [N])
         x[2] = delta_P_curtain (Deviation from target seal differential pressure [mbar])
         x[3] = delta_C_O2 (Oxygen concentration excess above baseline [ppm])
    *)
    rState_x1_SpeedErr              : REAL := 0.0;
    rState_x2_TensionErr            : REAL := 0.0;
    rState_x3_PressErr              : REAL := 0.0;
    rState_x4_O2Excess              : REAL := 0.0;

    (* System Dynamics State Transition Matrix (A_4x4) *)
    rA11 : REAL := 0.8250;  rA12 : REAL := -0.00045; rA13 : REAL := 0.0000;  rA14 : REAL := 0.0000;
    rA21 : REAL := 42.500;  rA22 : REAL := 0.89200;  rA23 : REAL := 0.0000;  rA24 : REAL := 0.0000;
    rA31 : REAL := 0.0000;  rA32 : REAL := 0.00000;  rA33 : REAL := 0.7450;  rA34 : REAL := -0.0018;
    rA41 : REAL := 0.0000;  rA42 : REAL := 0.00000;  rA43 : REAL := -4.120;  rA44 : REAL := 0.6800;

    (* Input Coupling Matrix (B_4x3) *)
    rB11 : REAL := 0.1750;  rB12 : REAL := 0.0000;   rB13 : REAL := 0.0000;
    rB21 : REAL := 18.200;  rB22 : REAL := 0.0000;   rB23 : REAL := 0.0000;
    rB31 : REAL := 0.0000;  rB32 : REAL := 0.00285;  rB33 : REAL := 0.00085;
    rB41 : REAL := 0.0000;  rB42 : REAL := -0.0152;  rB43 : REAL := -0.0945;

    (* Model Predictive Control Horizon Prediction Accumulators *)
    rPredSpeedErr_k1                : REAL := 0.0;
    rPredTensionErr_k1              : REAL := 0.0;
    rPredPressErr_k1                : REAL := 0.0;
    rPredO2Excess_k1                : REAL := 0.0;

    (* Target Process Operating Points *)
    rTargetTension_N                : REAL := 450.0; (* Optimal ribbon draw tension setpoint [N] *)
    rTargetDiffPressure_mbar        : REAL := 0.180; (* Positive barrier pressure setpoint [mbar] *)
    rTargetO2_ppm                   : REAL := 2.50;  (* Target protective atmosphere O2 cap [ppm] *)

    (* Glass Thermal Shrinkage & Expansion Parameters *)
    rAlphaGlass_PerDegC             : REAL := 9.0E-6;(* Linear coefficient of thermal expansion for soda-lime glass *)
    rAlphaRoller_PerDegC            : REAL := 0.54E-6;(* Thermal expansion of fused silica LOR roller sleeve *)
    rNominalRollerDia_m             : REAL := 0.305; (* Nominal diameter of LOR rollers [m] *)
    rEffectiveRollerDia_m           : REAL := 0.305;
    rThermalContractionTrim_mpm     : REAL := 0.0;

    (* Signal Conditioning & Filtering Accumulators *)
    rLehrSpeed_Filt                 : REAL := 0.0;
    rTinBathSpeed_Filt              : REAL := 0.0;
    rTension_Filt                   : REAL := 0.0;
    rO2_Filt                        : REAL := 0.0;
    rDiffPress_Filt                 : REAL := 0.0;

    (* Inter-Roller Draw Cascades *)
    rDrawRatio_LOR1                 : REAL := 0.0035; (* 0.35% draw elongation over tin bath *)
    rDrawRatio_LOR2                 : REAL := 0.0020; (* 0.20% draw elongation between LOR1 and LOR2 *)
    rDrawRatio_LOR3                 : REAL := 0.0015; (* 0.15% draw elongation between LOR2 and LOR3 *)

    (* Atmospheric Protective Gas Trim Controllers *)
    rN2BaseDemand_Pct               : REAL := 55.0;  (* Base baseline flow command [%] *)
    rH2BaseDemand_Pct               : REAL := 30.0;  (* Base hydrogen reducing command [%] *)
    rN2ModulatedTrim_Pct            : REAL := 0.0;
    rH2ModulatedTrim_Pct            : REAL := 0.0;

    (* Timers & Integrity Watchdogs *)
    tonStartupDelay                 : TON;
    tonAtmosphereStabilizeTimer     : TON;
    tonPressureLossDebounce         : TON;
    tonO2SpikeDebounce              : TON;
    tonTensionSurgeDebounce         : TON;
    tonStateTimer                   : TON;

    (* Statistical & Diagnostic Counters *)
    udiCycleCounter                 : UDINT := 0;
    udiAtmosphereExcursionCount     : UDINT := 0;
    udiTensionTripCount             : UDINT := 0;
END_VAR

(*
========================================================================================================================
  CYCLIC ALGORITHMIC EXECUTION PIPELINE
========================================================================================================================
*)

udiCycleCounter := udiCycleCounter + 1;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 1: HARDWIRED SAFETY INTERLOCKS & IMMEDIATE TRIP FIRST-OUT LOGIC (SIL-3 NFPA 86)
   --------------------------------------------------------------------------------------------------------------------- *)
IF NOT bSafetyEStopOk THEN
    (* Fail-Safe Emergency Drive & Atmosphere Isolation *)
    bSystemReady                := FALSE;
    bDegradedModeActive         := FALSE;
    bAtmosphereSealEstablished  := FALSE;

    (* Clamp all roller drive setpoints to immediate zero *)
    rLOR1_SpeedSetpoint_mpm     := 0.0;
    rLOR2_SpeedSetpoint_mpm     := 0.0;
    rLOR3_SpeedSetpoint_mpm     := 0.0;
    rCalculatedDraw_Pct         := 0.0;

    (* Atmosphere Safety Interlock: Open N2 deluge to prevent air back-siphon, shut down flammable H2 instantly *)
    rN2CurtainValveCmd_Pct      := 100.0; (* Full N2 safety inerting flush *)
    rH2CurtainValveCmd_Pct      := 0.0;   (* Immediate positive H2 safety shutoff valve trip *)

    wAlarmWord.0                := TRUE;  (* Alarm Bit 0: Emergency Safety Stop Activated *)
    wSystemStatusWord           := 16#F000;
    iState                      := 99;    (* Forced immediate transition to Emergency State *)
    RETURN;
END_IF;

wAlarmWord.0 := FALSE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 2: TRIPLE MODULAR REDUNDANCY (2oo3 TMR) DIFFERENTIAL PRESSURE SENSING
   --------------------------------------------------------------------------------------------------------------------- *)
(* Step 2.1: Sensor Engineering Range Plausibility Verification [0.00 mbar to 2.00 mbar] *)
bSensor1_Valid := (rBathExitDiffPress_Sens1_mbar >= 0.001) AND (rBathExitDiffPress_Sens1_mbar <= 1.950);
bSensor2_Valid := (rBathExitDiffPress_Sens2_mbar >= 0.001) AND (rBathExitDiffPress_Sens2_mbar <= 1.950);
bSensor3_Valid := (rBathExitDiffPress_Sens3_mbar >= 0.001) AND (rBathExitDiffPress_Sens3_mbar <= 1.950);

(* Step 2.2: Compute Pairwise Inter-Channel Discrepancy Residuals *)
rDelta12 := ABS(rBathExitDiffPress_Sens1_mbar - rBathExitDiffPress_Sens2_mbar);
rDelta23 := ABS(rBathExitDiffPress_Sens2_mbar - rBathExitDiffPress_Sens3_mbar);
rDelta31 := ABS(rBathExitDiffPress_Sens3_mbar - rBathExitDiffPress_Sens1_mbar);

(* Step 2.3: 2oo3 TMR Resolution & Sensor Fault Identification *)
IF bSensor1_Valid AND bSensor2_Valid AND bSensor3_Valid THEN
    IF (rDelta12 <= rTmrToleranceLimit) AND (rDelta23 <= rTmrToleranceLimit) AND (rDelta31 <= rTmrToleranceLimit) THEN
        (* Pristine 3-Channel Consensus: Full Triple Modular Average *)
        rVotedExitPressure_mbar := (rBathExitDiffPress_Sens1_mbar + rBathExitDiffPress_Sens2_mbar + rBathExitDiffPress_Sens3_mbar) / 3.0;
        iHealthySensorCount     := 3;
        wAlarmWord.1            := FALSE; (* TMR Divergence Warning Clear *)
    ELSIF (rDelta12 <= rTmrToleranceLimit) AND (rDelta23 > rTmrToleranceLimit) AND (rDelta31 > rTmrToleranceLimit) THEN
        (* Channel 3 Out of Tolerance: Reject Sensor 3, synthesize 1 and 2 *)
        rVotedExitPressure_mbar := (rBathExitDiffPress_Sens1_mbar + rBathExitDiffPress_Sens2_mbar) / 2.0;
        bSensor3_Valid          := FALSE;
        iHealthySensorCount     := 2;
        wAlarmWord.1            := TRUE;  (* TMR Channel 3 Divergence Alarm *)
    ELSIF (rDelta23 <= rTmrToleranceLimit) AND (rDelta12 > rTmrToleranceLimit) AND (rDelta31 > rTmrToleranceLimit) THEN
        (* Channel 1 Out of Tolerance: Reject Sensor 1, synthesize 2 and 3 *)
        rVotedExitPressure_mbar := (rBathExitDiffPress_Sens2_mbar + rBathExitDiffPress_Sens3_mbar) / 2.0;
        bSensor1_Valid          := FALSE;
        iHealthySensorCount     := 2;
        wAlarmWord.1            := TRUE;  (* TMR Channel 1 Divergence Alarm *)
    ELSIF (rDelta31 <= rTmrToleranceLimit) AND (rDelta12 > rTmrToleranceLimit) AND (rDelta23 > rTmrToleranceLimit) THEN
        (* Channel 2 Out of Tolerance: Reject Sensor 2, synthesize 1 and 3 *)
        rVotedExitPressure_mbar := (rBathExitDiffPress_Sens1_mbar + rBathExitDiffPress_Sens3_mbar) / 2.0;
        bSensor2_Valid          := FALSE;
        iHealthySensorCount     := 2;
        wAlarmWord.1            := TRUE;  (* TMR Channel 2 Divergence Alarm *)
    ELSE
        (* Total TMR Incoherence: Divergence across all pairs *)
        rVotedExitPressure_mbar := (rBathExitDiffPress_Sens1_mbar + rBathExitDiffPress_Sens2_mbar + rBathExitDiffPress_Sens3_mbar) / 3.0;
        iHealthySensorCount     := 1;
        wAlarmWord.1            := TRUE;
        wAlarmWord.2            := TRUE;  (* Critical TMR Incoherence Fault *)
    END_IF;
ELSIF bSensor1_Valid AND bSensor2_Valid THEN
    rVotedExitPressure_mbar := (rBathExitDiffPress_Sens1_mbar + rBathExitDiffPress_Sens2_mbar) / 2.0;
    iHealthySensorCount     := 2;
    wAlarmWord.1            := TRUE;
ELSIF bSensor2_Valid AND bSensor3_Valid THEN
    rVotedExitPressure_mbar := (rBathExitDiffPress_Sens2_mbar + rBathExitDiffPress_Sens3_mbar) / 2.0;
    iHealthySensorCount     := 2;
    wAlarmWord.1            := TRUE;
ELSIF bSensor1_Valid AND bSensor3_Valid THEN
    rVotedExitPressure_mbar := (rBathExitDiffPress_Sens1_mbar + rBathExitDiffPress_Sens3_mbar) / 2.0;
    iHealthySensorCount     := 2;
    wAlarmWord.1            := TRUE;
ELSIF bSensor1_Valid THEN
    rVotedExitPressure_mbar := rBathExitDiffPress_Sens1_mbar;
    iHealthySensorCount     := 1;
    wAlarmWord.2            := TRUE;
ELSIF bSensor2_Valid THEN
    rVotedExitPressure_mbar := rBathExitDiffPress_Sens2_mbar;
    iHealthySensorCount     := 1;
    wAlarmWord.2            := TRUE;
ELSIF bSensor3_Valid THEN
    rVotedExitPressure_mbar := rBathExitDiffPress_Sens3_mbar;
    iHealthySensorCount     := 1;
    wAlarmWord.2            := TRUE;
ELSE
    (* Total Sensor Failure: Deterministic Safe Value with Emergency Curtain Boost *)
    rVotedExitPressure_mbar := 0.050;
    iHealthySensorCount     := 0;
    wAlarmWord.2            := TRUE;
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 3: SIGNAL FILTERING, KINEMATICS & STATE-SPACE MODEL COMPUTATION
   --------------------------------------------------------------------------------------------------------------------- *)
(* First-order digital low-pass filtering on velocities and process pressures *)
rLehrSpeed_Filt     := (rLehrSpeed_Filt * 0.85) + (rLehrMasterSpeed_mpm * 0.15);
rTinBathSpeed_Filt  := (rTinBathSpeed_Filt * 0.85) + (rTinBathRibbonSpeed_mpm * 0.15);
rTension_Filt       := (rTension_Filt * 0.80) + (rRibbonTensionFeedback_N * 0.20);
rO2_Filt            := (rO2_Filt * 0.70) + (rOxygenPpm_BathExit_ppm * 0.30);
rDiffPress_Filt     := (rDiffPress_Filt * 0.75) + (rVotedExitPressure_mbar * 0.25);

(* Glass Thermal Contraction Speed Compensation *)
(* As glass drops from ~600 deg C to ~550 deg C across transition, it contracts *)
IF (rGlassRibbonTemp_DegC > 500.0) AND (rGlassRibbonTemp_DegC < 700.0) THEN
    rThermalContractionTrim_mpm := rTinBathSpeed_Filt * rAlphaGlass_PerDegC * (rGlassRibbonTemp_DegC - 550.0);
ELSE
    rThermalContractionTrim_mpm := 0.0;
END_IF;

(* Roller Diameter Thermal Expansion Compensation *)
IF (rLOR_BottomRollTemp_DegC > 200.0) AND (rLOR_BottomRollTemp_DegC < 700.0) THEN
    rEffectiveRollerDia_m := rNominalRollerDia_m * (1.0 + (rAlphaRoller_PerDegC * (rLOR_BottomRollTemp_DegC - 20.0)));
ELSE
    rEffectiveRollerDia_m := rNominalRollerDia_m;
END_IF;

(* State Deviation Vector Construction *)
rState_x1_SpeedErr   := (rTinBathSpeed_Filt - rLehrSpeed_Filt);
rState_x2_TensionErr := (rTargetTension_N - rTension_Filt);
rState_x3_PressErr   := (rTargetDiffPressure_mbar - rDiffPress_Filt);
rState_x4_O2Excess   := (rO2_Filt - rTargetO2_ppm);

(* One-Step Ahead State-Space Receding Horizon Projection *)
rPredSpeedErr_k1   := (rA11 * rState_x1_SpeedErr)   + (rA12 * rState_x2_TensionErr);
rPredTensionErr_k1 := (rA21 * rState_x1_SpeedErr)   + (rA22 * rState_x2_TensionErr);
rPredPressErr_k1   := (rA33 * rState_x3_PressErr)   + (rA34 * rState_x4_O2Excess);
rPredO2Excess_k1   := (rA43 * rState_x3_PressErr)   + (rA44 * rState_x4_O2Excess);

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 4: SEQUENTIAL FINITE STATE MACHINE (ISA-88 MODULAR OPERATIONS)
   --------------------------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE_INIT_DIAGNOSTICS: Pre-Start System Verification & Actuator Check *)
        bSystemReady                := FALSE;
        bDegradedModeActive         := FALSE;
        bAtmosphereSealEstablished  := FALSE;
        rLOR1_SpeedSetpoint_mpm     := 0.0;
        rLOR2_SpeedSetpoint_mpm     := 0.0;
        rLOR3_SpeedSetpoint_mpm     := 0.0;
        rN2CurtainValveCmd_Pct      := 20.0; (* Pre-purge gentle blanket *)
        rH2CurtainValveCmd_Pct      := 0.0;  (* Inhibit H2 until N2 seal verified *)
        rCalculatedDraw_Pct         := 0.0;
        wSystemStatusWord           := 16#0001;

        tonStartupDelay(IN := bMasterEnable, PT := T#10S);
        IF tonStartupDelay.Q THEN
            tonStartupDelay(IN := FALSE);
            IF (iHealthySensorCount >= 2) AND NOT bGraphiteSealWearAlarm THEN
                iState := 10; (* Advance to Atmosphere Seal Establishment *)
            ELSE
                wAlarmWord.3 := TRUE; (* Seal integrity or sensor failure hold *)
            END_IF;
        END_IF;

    10: (* STATE_ATMOSPHERE_ESTABLISH_SEAL: Build Positive N2/H2 Barrier Pressure *)
        bSystemReady                := FALSE;
        bDegradedModeActive         := FALSE;
        wSystemStatusWord           := 16#0010;

        (* Modulate N2 to build positive barrier pressure > 0.15 mbar *)
        rN2CurtainValveCmd_Pct      := 65.0;
        rH2CurtainValveCmd_Pct      := 15.0; (* Introduce reducing trim *)
        rLOR1_SpeedSetpoint_mpm     := 0.0;
        rLOR2_SpeedSetpoint_mpm     := 0.0;
        rLOR3_SpeedSetpoint_mpm     := 0.0;

        tonAtmosphereStabilizeTimer(IN := (rDiffPress_Filt >= 0.120) AND (rO2_Filt <= 5.0), PT := T#15S);
        IF tonAtmosphereStabilizeTimer.Q THEN
            tonAtmosphereStabilizeTimer(IN := FALSE);
            bAtmosphereSealEstablished := TRUE;
            IF bAutoModeSelect THEN
                iState := 20; (* Advance to Synchronized Drive Ramp *)
            END_IF;
        ELSIF NOT bMasterEnable THEN
            iState := 0;
        END_IF;

    20: (* STATE_LOR_SYNC_RAMP_ENGAGE: Synchronize LOR Line Speed with Tin Bath *)
        bSystemReady                := TRUE;
        bDegradedModeActive         := FALSE;
        wSystemStatusWord           := 16#0020;

        (* Compute progressive speed draw cascade *)
        rLOR1_SpeedSetpoint_mpm := (rTinBathSpeed_Filt * (1.0 + rDrawRatio_LOR1)) - (rThermalContractionTrim_mpm * 0.33);
        rLOR2_SpeedSetpoint_mpm := (rLOR1_SpeedSetpoint_mpm * (1.0 + rDrawRatio_LOR2)) - (rThermalContractionTrim_mpm * 0.33);
        rLOR3_SpeedSetpoint_mpm := (rLOR2_SpeedSetpoint_mpm * (1.0 + rDrawRatio_LOR3)) - (rThermalContractionTrim_mpm * 0.34);

        (* Hold stable atmosphere curtains *)
        rN2CurtainValveCmd_Pct  := rN2BaseDemand_Pct;
        rH2CurtainValveCmd_Pct  := rH2BaseDemand_Pct;

        (* Verify ribbon tension has engaged within normal envelope [200 N .. 800 N] *)
        IF (rTension_Filt >= 220.0) AND (rTension_Filt <= 750.0) THEN
            iState := 30; (* Engage Full Closed-Loop State-Space MPC *)
        ELSIF NOT bMasterEnable THEN
            iState := 0;
        END_IF;

    30: (* STATE_FULL_CASCADE_MPC_STEADY: Optimal Multivariable Speed & Atmosphere Regulation *)
        bSystemReady        := TRUE;
        bDegradedModeActive := (iHealthySensorCount < 3);
        wSystemStatusWord   := 16#0030;

        (* --- MPC Kinematic Control Calculation --- *)
        (* Adaptive draw ratio trim based on model prediction and glass thickness *)
        (* Thicker glass requires lower draw strain; thinner glass requires higher draw stiffness *)
        IF rGlassThickness_mm > 0.0 THEN
            rDrawRatio_LOR1 := 0.0030 + (0.0035 / rGlassThickness_mm);
        ELSE
            rDrawRatio_LOR1 := 0.0035;
        END_IF;

        (* LOR Speed cascade with tension compensation feedback *)
        rLOR1_SpeedSetpoint_mpm := (rTinBathSpeed_Filt * (1.0 + rDrawRatio_LOR1))
                                   + (rPredTensionErr_k1 * 0.000085)
                                   - (rThermalContractionTrim_mpm * 0.33);

        rLOR2_SpeedSetpoint_mpm := (rLOR1_SpeedSetpoint_mpm * (1.0 + rDrawRatio_LOR2))
                                   + (rPredTensionErr_k1 * 0.000045)
                                   - (rThermalContractionTrim_mpm * 0.33);

        rLOR3_SpeedSetpoint_mpm := (rLOR2_SpeedSetpoint_mpm * (1.0 + rDrawRatio_LOR3))
                                   + (rPredTensionErr_k1 * 0.000020)
                                   - (rThermalContractionTrim_mpm * 0.34);

        (* Clamp LOR3 speed to Lehr line speed boundary to prevent slippage *)
        IF ABS(rLOR3_SpeedSetpoint_mpm - rLehrSpeed_Filt) > 0.50 THEN
            rLOR3_SpeedSetpoint_mpm := rLehrSpeed_Filt;
        END_IF;

        (* Calculate overall draw elongation percentage [%] *)
        IF rTinBathSpeed_Filt > 0.1 THEN
            rCalculatedDraw_Pct := ((rLOR3_SpeedSetpoint_mpm - rTinBathSpeed_Filt) / rTinBathSpeed_Filt) * 100.0;
        ELSE
            rCalculatedDraw_Pct := 0.0;
        END_IF;

        (* --- MPC Protective Atmosphere Curtain Modulation --- *)
        (* Nitrogen curtain pressure feedback compensation *)
        rN2ModulatedTrim_Pct := (rPredPressErr_k1 * 125.0) + (rPredO2Excess_k1 * 1.85);
        rN2CurtainValveCmd_Pct := rN2BaseDemand_Pct + rN2ModulatedTrim_Pct;
        IF rN2CurtainValveCmd_Pct > 95.0 THEN
            rN2CurtainValveCmd_Pct := 95.0;
        ELSIF rN2CurtainValveCmd_Pct < 30.0 THEN
            rN2CurtainValveCmd_Pct := 30.0;
        END_IF;

        (* Hydrogen reducing trim modulation (capped for safety) *)
        rH2ModulatedTrim_Pct := (rPredO2Excess_k1 * 4.20) - (rPredPressErr_k1 * 15.0);
        rH2CurtainValveCmd_Pct := rH2BaseDemand_Pct + rH2ModulatedTrim_Pct;
        IF rH2CurtainValveCmd_Pct > 55.0 THEN
            rH2CurtainValveCmd_Pct := 55.0; (* NFPA 86 safety limit cap *)
        ELSIF rH2CurtainValveCmd_Pct < 5.0 THEN
            rH2CurtainValveCmd_Pct := 5.0;
        END_IF;

        (* State Machine Transient Triggers *)
        IF (rTension_Filt > 900.0) OR (rTension_Filt < 150.0) THEN
            iState := 40; (* Tension Surge / Slack Transient *)
        ELSIF (rDiffPress_Filt < 0.070) OR (rO2_Filt > 10.0) THEN
            iState := 50; (* Atmosphere Barrier Ingress Mitigation *)
        ELSIF (iHealthySensorCount <= 1) THEN
            iState := 60; (* Degraded Sensor Fallback *)
        END_IF;

    40: (* STATE_TENSION_SURGE_TRANSIENT: Immediate Tension Relief & Buckling Avoidance *)
        bSystemReady                := TRUE;
        bDegradedModeActive         := TRUE;
        wSystemStatusWord           := 16#0040;
        wAlarmWord.4                := TRUE; (* Tension Deviation Alarm Active *)
        udiTensionTripCount         := udiTensionTripCount + 1;

        IF rTension_Filt > 900.0 THEN
            (* Ribbon Over-Tension Hazard: Decelerate LOR cascade instantly by 0.8% to relieve strain *)
            rLOR1_SpeedSetpoint_mpm := rTinBathSpeed_Filt * 0.998;
            rLOR2_SpeedSetpoint_mpm := rTinBathSpeed_Filt * 0.999;
            rLOR3_SpeedSetpoint_mpm := rTinBathSpeed_Filt * 1.000;
        ELSE
            (* Ribbon Under-Tension Sag Hazard: Accelerate LOR cascade to pick up slack *)
            rLOR1_SpeedSetpoint_mpm := rTinBathSpeed_Filt * 1.008;
            rLOR2_SpeedSetpoint_mpm := rTinBathSpeed_Filt * 1.012;
            rLOR3_SpeedSetpoint_mpm := rTinBathSpeed_Filt * 1.015;
        END_IF;

        (* Maintain rigid N2 blanket *)
        rN2CurtainValveCmd_Pct := 75.0;
        rH2CurtainValveCmd_Pct := 20.0;

        (* Exit condition: tension normalized within [300 N .. 600 N] *)
        IF (rTension_Filt >= 300.0) AND (rTension_Filt <= 600.0) THEN
            wAlarmWord.4 := FALSE;
            iState := 30; (* Return to steady MPC *)
        ELSIF (rTension_Filt > 1300.0) OR (rTension_Filt < 50.0) THEN
            (* Catastrophic ribbon tear or drop: Trip to emergency *)
            iState := 99;
        END_IF;

    50: (* STATE_ATMOSPHERE_INGRESS_RECOVERY: High-Pressure N2 Purge Barrier Restoration *)
        bSystemReady                := TRUE;
        bDegradedModeActive         := TRUE;
        wSystemStatusWord           := 16#0050;
        wAlarmWord.5                := TRUE; (* Atmosphere Barrier Ingress Alarm *)
        udiAtmosphereExcursionCount := udiAtmosphereExcursionCount + 1;

        (* Boost Nitrogen curtain flow to full seal capacity *)
        rN2CurtainValveCmd_Pct      := 98.0;
        (* Inhibit excess H2 to prevent flammable mixture in high-oxygen ingress event *)
        IF rO2_Filt > 25.0 THEN
            rH2CurtainValveCmd_Pct  := 0.0;  (* Safety cut of H2 on high oxygen *)
            wAlarmWord.6            := TRUE; (* H2 Inhibit Bit *)
        ELSE
            rH2CurtainValveCmd_Pct  := 10.0;
            wAlarmWord.6            := FALSE;
        END_IF;

        (* Maintain conservative constant-ratio speed cascade *)
        rLOR1_SpeedSetpoint_mpm := rTinBathSpeed_Filt * 1.003;
        rLOR2_SpeedSetpoint_mpm := rTinBathSpeed_Filt * 1.005;
        rLOR3_SpeedSetpoint_mpm := rTinBathSpeed_Filt * 1.007;

        (* Exit condition: differential pressure restored > 0.14 mbar and O2 < 4.0 ppm *)
        IF (rDiffPress_Filt >= 0.140) AND (rO2_Filt <= 4.0) THEN
            wAlarmWord.5 := FALSE;
            wAlarmWord.6 := FALSE;
            iState := 30; (* Re-enter steady-state MPC *)
        END_IF;

    60: (* STATE_DEGRADED_VIRTUAL_GEAR: Sensor Loss Fallback / Virtual Electronic Line Shaft *)
        bSystemReady            := TRUE;
        bDegradedModeActive     := TRUE;
        wSystemStatusWord       := 16#0060;
        wAlarmWord.7            := TRUE; (* Degraded Operation Status Active *)

        (* Hardcoded feedforward ratio synchronization independent of load cells *)
        rLOR1_SpeedSetpoint_mpm := rLehrSpeed_Filt * 0.995;
        rLOR2_SpeedSetpoint_mpm := rLehrSpeed_Filt * 0.997;
        rLOR3_SpeedSetpoint_mpm := rLehrSpeed_Filt * 1.000;

        (* Fixed conservative gas flow commands *)
        rN2CurtainValveCmd_Pct  := 70.0;
        rH2CurtainValveCmd_Pct  := 25.0;

        IF (iHealthySensorCount >= 2) AND bAutoModeSelect THEN
            wAlarmWord.7 := FALSE;
            iState := 30; (* Re-enable closed-loop MPC *)
        END_IF;

    99: (* STATE_SAFETY_ESTOP_LINE_TRIP: Emergency Process Halt & Ribbon Breakage Containment *)
        bSystemReady                := FALSE;
        bDegradedModeActive         := FALSE;
        bAtmosphereSealEstablished  := FALSE;
        rLOR1_SpeedSetpoint_mpm     := 0.0;
        rLOR2_SpeedSetpoint_mpm     := 0.0;
        rLOR3_SpeedSetpoint_mpm     := 0.0;
        rCalculatedDraw_Pct         := 0.0;
        rN2CurtainValveCmd_Pct      := 100.0; (* Full inerting blanket *)
        rH2CurtainValveCmd_Pct      := 0.0;   (* Total H2 isolation *)
        wSystemStatusWord           := 16#9999;
        wAlarmWord.0                := TRUE;

        IF bSafetyEStopOk AND (rTension_Filt < 100.0) THEN
            iState := 0; (* Reset sequence *)
        END_IF;

END_CASE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 5: SECONDARY ALARM HIERARCHIES & GRAPHITE SEAL INTEGRITY (ISA-18.2)
   --------------------------------------------------------------------------------------------------------------------- *)
(* Bottom Graphite Seal Mechanical Wear Alarm *)
IF bGraphiteSealWearAlarm THEN
    wAlarmWord.8 := TRUE; (* Seal mechanical limit warning *)
ELSE
    wAlarmWord.8 := FALSE;
END_IF;

(* Oxygen High-High Emergency Alarm (NFPA 86 Class C Atmosphere Limit) *)
IF rO2_Filt > 45.0 THEN
    wAlarmWord.9 := TRUE; (* Extreme oxygen excursion *)
    rH2CurtainValveCmd_Pct := 0.0; (* Hard safety interlock on hydrogen *)
ELSE
    wAlarmWord.9 := FALSE;
END_IF;

(* Dross Box Over-Temperature Thermal Protection *)
IF rDrossBoxCavityTemp_DegC > 580.0 THEN
    wAlarmWord.10 := TRUE; (* Thermal distortion warning for LOR support bearings *)
ELSE
    wAlarmWord.10 := FALSE;
END_IF;

